const DORMANT_THRESHOLD_DAYS = 30; // change this to adjust the re-engagement window

const today = new Date();
const dormant = [];
const skipped = [];

for (const item of $input.all()) {
  const lead = item.json;
  const status = (lead['Status'] || '').trim();
  const email = (lead['Email'] || '').trim();
  const lastContact = lead['Last Contact Date'] 
    ? new Date(lead['Last Contact Date']) 
    : null;

  // Exclude Do Not Contact leads
  if (status.toLowerCase() === 'do not contact') {
    skipped.push({ name: lead['Lead Name'], reason: 'Do Not Contact' });
    continue;
  }

  // Exclude leads with no email
  if (!email) {
    skipped.push({ name: lead['Lead Name'], reason: 'No email on file' });
    continue;
  }

  // Exclude leads with no last contact date (treat as new, not dormant)
  if (!lastContact || isNaN(lastContact.getTime())) {
    skipped.push({ name: lead['Lead Name'], reason: 'No contact date recorded' });
    continue;
  }

  // Calculate days since last contact
  const daysSinceContact = Math.floor(
    (today - lastContact) / (1000 * 60 * 60 * 24)
  );

  // Exclude recently contacted leads
  if (daysSinceContact < DORMANT_THRESHOLD_DAYS) {
    skipped.push({ 
      name: lead['Lead Name'], 
      reason: `Contacted ${daysSinceContact} days ago — not yet dormant` 
    });
    continue;
  }

  // Lead is dormant — include for re-engagement
  dormant.push({
    json: {
      recordId: lead['recordId'],
      leadName: lead['Lead Name'],
      leadEmail: email,
      leadPhone: lead['Phone'] || '',
      propertyInterest: lead['Property Interest'] || 'a property you enquired about',
      lastContactDate: lead['Last Contact Date'],
      daysSinceContact,
      reEngagementCount: parseInt(lead['Re-Engagement Attempt Count'] || '0'),
      status: lead['Status']
    }
  });
}

// Store skipped leads summary in a global static node for digest use later
// (passed forward via the first dormant item or a separate output)
const summary = {
  totalScanned: $input.all().length,
  dormantCount: dormant.length,
  skippedCount: skipped.length,
  skippedReasons: skipped
};

// Attach summary to every dormant item so it's available downstream
return dormant.map(item => ({
  json: { ...item.json, runSummary: summary }
}));

