const raw = $input.first().json.output;
const leadData = $('Loop Over Items').item.json; 

let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  parsed = {
    email_subject: `Checking in — still interested in ${leadData.propertyInterest}?`,
    email_body: `Hi ${leadData.leadName},\n\nI wanted to reach out and see if you're still interested in finding the right property. I'd love to help whenever the timing is right for you — no pressure at all.`
  };
}

function escapeHtml(text) {
  return text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

function formatEmailHtml(text) {
  const paragraphs = text
    .split(/\n\s*\n/)
    .map(p => p.replace(/\s+/g, ' ').trim())
    .filter(Boolean);
  return paragraphs.map(p => `<p>${escapeHtml(p)}</p>`).join('');
}

return [{
  json: {
    ...leadData,
    email_subject: parsed.email_subject,
    email_body: formatEmailHtml(parsed.email_body)
  }
}];

// Pull lead data from Filter node — reliable source outside the loop
const filterItems = $('Filter: Dormant Leads Only').all();
const fetchItems = $('Fetch All Leads').all();

const totalScanned = fetchItems.length;
const dormantCount = filterItems.length;
const skippedCount = totalScanned - dormantCount;

// Build contacted list from Filter node items
const contacted = filterItems.map(item => ({
  name: item.json.leadName,
  email: item.json.leadEmail,
  property: item.json.propertyInterest || 'a property you enquired about',
  daysDormant: item.json.daysSinceContact
}));

// Guard against undefined fields
function safeVal(val, fallback = 'N/A') {
  return val !== undefined && val !== null && val !== '' ? val : fallback;
}

// Build digest HTML
const digestHtml = `
  <p><strong>Winback Run Summary — ${new Date().toDateString()}</strong></p>
  <p>
    Total leads scanned: ${totalScanned}<br>
    Re-engagement emails sent: ${contacted.length}<br>
    Leads skipped: ${skippedCount}
  </p>
  <p><strong>Emails sent to:</strong></p>
  <p>${contacted.length > 0
    ? contacted.map(l =>
        `${safeVal(l.name)} (${safeVal(l.email)}) — ${safeVal(l.property)} — ${safeVal(l.daysDormant)} days dormant`
      ).join('<br>')
    : 'No dormant leads found in this run.'
  }</p>
  ${skippedCount > 0 ? `
  <p><strong>Leads skipped:</strong> ${skippedCount} (check sheet for Do Not Contact, missing email, or recently contacted leads)</p>
  ` : ''}
`;

// Build Slack digest
const contactedLines = contacted.map(
  l => `• ${safeVal(l.name)} (${safeVal(l.email)}) — ${safeVal(l.property)} — ${safeVal(l.daysDormant)} days dormant`
).join('\n');

const slackDigest =
  `📋 *Winback Run — ${new Date().toDateString()}*\n` +
  `Scanned: ${totalScanned} | Sent: ${contacted.length} | Skipped: ${skippedCount}\n\n` +
  (contacted.length > 0
    ? `*Emailed:*\n${contactedLines}`
    : '_No dormant leads found today._');

return [{
  json: {
    digestHtml,
    slackDigest,
    totalScanned,
    emailsSent: contacted.length,
    skippedCount
  }
}];
